'use strict';
const D=globalThis.RISKLENS_DATA,M=RiskEngine.analyze(D),$=s=>document.querySelector(s);
const money=n=>'₹'+n.toLocaleString('en-IN');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let reviews={};try{reviews=JSON.parse(localStorage.getItem('risklens-reviews')||'{}')}catch{}
let selected=M.alerts[0]?.account_id,contextAccount=null;
const status=id=>reviews[id]?.status||'Open';
function save(){try{localStorage.setItem('risklens-reviews',JSON.stringify(reviews))}catch{alert('Browser storage unavailable. Export your report before leaving.')}}
function download(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function csv(rows){if(!rows.length)return '';const keys=Object.keys(rows[0]);const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"';return [keys.map(cell).join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n')}
function evidenceTable(rows){return `<div class="table-wrap"><table><thead><tr><th>TRANSACTION</th><th>TIME · UTC</th><th>AMOUNT · INR</th><th>BENEFICIARY</th><th>AGE</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${esc(t.transaction_id)}</td><td>${esc(t.transaction_time.replace('T',' '))}</td><td>${money(t.amount)}</td><td>${esc(t.beneficiary_id)}</td><td>${t.beneficiary_age_days}d</td></tr>`).join('')}</tbody></table></div>`}
function accountTable(rows){return `<table><thead><tr><th>ACCOUNT / CUSTOMER</th><th>SEVERITY</th><th>SIGNALS</th><th>FLAGGED AMOUNT</th><th>STATUS</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td><button class="account-btn" data-account="${a.account_id}">${a.account_id}</button><br><small>${esc(a.customer_name)}</small></td><td><span class="severity ${a.severity}">${a.severity}</span></td><td>${a.signals.length}</td><td>${money(a.exposure)}</td><td>${esc(status(a.account_id))}</td><td><button class="link" data-account="${a.account_id}">Investigate →</button></td></tr>`).join('')}</tbody></table>`}
function overview(){const high=M.alerts.filter(a=>a.severity==='High').length;$('#stats').innerHTML=[['Payments monitored',M.transactions.length,'September 2026 · outgoing INR payments'],['Accounts flagged',M.alerts.length,`${high} high priority · ${M.alerts.length-high} medium priority`],['Flagged payment amount',money(M.exposure),`${M.flagged.length} unique transactions · deduplicated`],['Total monitored amount',money(M.total),'Sum of all monitored outgoing payments']].map(([l,v,s])=>`<div class="stat"><div class="stat-label">${l}</div><div class="stat-value">${v}</div><div class="stat-sub">${s}</div></div>`).join('');$('#nav-count').textContent=M.alerts.length;$('#overview-table').innerHTML=accountTable(M.alerts);$('#risk-bars').innerHTML=D.policies.map(p=>{const n=M.alerts.filter(a=>a.signals.some(s=>s.policy===p.id)).length;return `<div class="bar-item"><div class="bar-label"><span>${esc(p.name)}</span><strong>${n} accounts</strong></div><div class="bar-track"><div class="bar-fill" style="width:${n/M.alerts.length*100}%"></div></div></div>`}).join('');$('#overview-insight').innerHTML=`<strong>${selected||'A104'}</strong> is currently selected. Amounts are deduplicated across signals; policy counts may overlap. Open a case to inspect its evidence.`}
function page(id){document.querySelectorAll('.page').forEach(e=>e.classList.toggle('hidden',e.id!==id));document.querySelectorAll('.nav').forEach(e=>e.classList.toggle('active',e.dataset.page===id));$('#page-title').textContent={overview:'Risk overview',investigate:'Investigations',copilot:'Ask RiskLens',policies:'Policies & provenance'}[id];if(id==='investigate')renderQueue()}
function renderQueue(){const q=$('#account-search').value.toLowerCase(),sev=$('#severity').value,st=$('#status-filter').value;const rows=M.alerts.filter(a=>(a.account_id+' '+a.customer_name).toLowerCase().includes(q)&&(sev==='all'||a.severity===sev)&&(st==='all'||status(a.account_id)===st));if(!rows.some(a=>a.account_id===selected))selected=rows[0]?.account_id;$('#queue-count').textContent=rows.length+' cases';$('#queue').innerHTML=rows.length?rows.map(a=>`<button class="queue-item ${a.account_id===selected?'selected':''}" data-select="${a.account_id}"><div class="meta"><span>${a.account_id}</span><span class="severity ${a.severity}">${a.severity}</span></div><strong>${esc(a.customer_name)}</strong><div class="meta"><span>${money(a.exposure)}</span><span>${esc(status(a.account_id))}</span></div></button>`).join(''):'<p class="empty">No cases match these filters.</p>';renderCase()}
function report(a){return {report_type:'Investigation draft — synthetic data',case_id:'CASE-'+a.account_id,snapshot:D.snapshot,generated_at:new Date().toISOString(),account_id:a.account_id,customer_name:a.customer_name,currency:'INR',severity:a.severity,flagged_payment_amount:a.exposure,review_status:status(a.account_id),reviewer_notes:reviews[a.account_id]?.notes||'',signals:a.signals.map(s=>({policy_id:s.policy,policy_version:'1.0',rule:D.policies.find(p=>p.id===s.policy).rule,evidence_transaction_ids:s.rows.map(t=>t.transaction_id)})),evidence:a.evidence,limitations:['Synthetic data; no fraud verdict','Internal demo policies; not regulatory rules','Local browser review storage; no tamper-proof audit log','No live Snowflake or LLM in this hosted demo']}}
function renderCase(){const a=M.alerts.find(a=>a.account_id===selected);if(!a){$('#case-detail').innerHTML='<p class="empty">Select an investigation to inspect evidence.</p>';return}$('#case-detail').innerHTML=`<div class="case-top"><div><span class="eyebrow">CASE-${a.account_id} · SEPTEMBER 2026</span><h2>${esc(a.customer_name)}</h2><span class="muted">Account ${a.account_id} · typical historical payment ${money(a.baseline_amount)}</span></div><span class="severity ${a.severity}">${a.severity} priority</span></div><div class="case-meta"><span class="badge">${a.signals.length} policy signals</span><span class="badge">${a.evidence.length} evidence rows</span><span class="badge">${money(a.exposure)} flagged</span></div><h3>Why this account needs review</h3>${a.signals.map(s=>`<div class="signal-card"><strong>${esc(s.name)} <span class="badge">${s.policy} · v1.0</span></strong><p>${esc(D.policies.find(p=>p.id===s.policy).rule)}</p><small>Evidence: ${s.rows.map(t=>t.transaction_id).join(', ')}</small></div>`).join('')}<h2>Transaction evidence</h2>${evidenceTable(a.evidence)}<button class="link" id="export-case-csv">↓ Download case evidence CSV</button><div class="case-review"><h3>Analyst review</h3><p class="muted">Document your assessment. Changes are stored in this browser.</p><label for="notes">Reviewer notes<textarea id="notes" maxlength="5000" placeholder="What needs follow-up?">${esc(reviews[a.account_id]?.notes||'')}</textarea></label><div class="review-actions"><label>Review status<select id="case-status">${['Open','In review','Escalated','Closed'].map(s=>`<option ${s===status(a.account_id)?'selected':''}>${s}</option>`).join('')}</select></label><div><button class="button secondary" id="save-review">Save review</button> <button class="button" id="export-report">↓ Export case report</button></div></div><p id="save-feedback" class="muted" aria-live="polite"></p></div>`;$('#save-review').onclick=()=>{reviews[a.account_id]={status:$('#case-status').value,notes:$('#notes').value};save();overview();$('#save-feedback').textContent='Review saved in this browser.';renderQueue()};$('#export-case-csv').onclick=()=>download(a.account_id+'-evidence.csv',csv(a.evidence),'text/csv');$('#export-report').onclick=()=>{reviews[a.account_id]={status:$('#case-status').value,notes:$('#notes').value};save();download('CASE-'+a.account_id+'.json',JSON.stringify(report(a),null,2),'application/json')}}
function answer(question){let q=question.toLowerCase();const found=question.match(/\bA\d{3}\b/i);if(found)contextAccount=found[0].toUpperCase();if(/202[0-57-9]|october|august|last month|today|yesterday|this year/.test(q))return '<p>This snapshot covers September 2026 only. Ask using that period. No answer is computed for an unsupported date range.</p>';if(/policy|policies|rule|threshold/.test(q))return D.policies.map(p=>`<h3>${p.id}: ${esc(p.name)}</h3><p>${esc(p.rule)} Citation: internal demo policy v${p.version}.</p>`).join('');if(/exposure|total|amount|how much/.test(q)&&!found&&!/its|that account/.test(q))return `<h3>${money(M.exposure)} flagged payment amount</h3><p>Across ${M.flagged.length} unique payments and ${M.alerts.length} accounts. This is the sum of flagged payment amounts, not an estimate of financial loss.</p><details><summary>Computation & provenance</summary><pre>SUM(amount) over distinct flagged transaction IDs\nPeriod: 2026-09-01 ≤ timestamp &lt; 2026-10-01\nCurrency: INR · outgoing payments only</pre></details>`;if(found||((/why|transactions|evidence|report|explain|its/.test(q))&&contextAccount)){const a=M.alerts.find(a=>a.account_id===contextAccount),account=D.accounts.find(a=>a.account_id===contextAccount);if(!account)return '<p>That account is not in the synthetic dataset.</p>';if(!a)return `<p>Account ${esc(contextAccount)} triggered no configured rules in September 2026. This does not establish that the account is risk-free.</p>`;return `<h3>${a.account_id} · ${esc(a.customer_name)}</h3><p>${a.signals.length} signals; ${a.evidence.length} unique evidence rows; ${money(a.exposure)} flagged.</p>${a.signals.map(s=>`<p><strong>${esc(s.name)}</strong> — ${esc(D.policies.find(p=>p.id===s.policy).rule)} [${s.policy}, v1.0]</p>`).join('')}${evidenceTable(a.evidence)}<button class="link" data-account="${a.account_id}">Open case and export investigation report →</button>`}if(/accounts|alerts|flagged|suspicious|risk/.test(q))return `<h3>${M.alerts.length} accounts require review</h3><p>September 2026 · ${M.flagged.length} unique flagged payments. Priority follows documented rules, not an AI probability score.</p>${accountTable(M.alerts)}`;return '<p>I can list September 2026 alerts, explain a specific account, show evidence, calculate flagged payment exposure, or explain policies. This demo uses supported question routing, not a general-purpose LLM.</p>'}
function ask(q){$('#messages').insertAdjacentHTML('beforeend',`<div class="message user">${esc(q)}</div><div class="message"><span class="eyebrow">RISKLENS · COMPUTED FROM DEMO DATA</span>${answer(q)}</div>`);$('#question').value='';$('#messages').lastElementChild.scrollIntoView({behavior:'smooth',block:'nearest'})}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]'),go=e.target.closest('[data-go]'),a=e.target.closest('[data-account]'),s=e.target.closest('[data-select]');if(nav)page(nav.dataset.page);if(go)page(go.dataset.go);if(a){selected=a.dataset.account;contextAccount=selected;page('investigate');renderQueue()}if(s){selected=s.dataset.select;renderQueue()}});
$('#account-search').oninput=renderQueue;$('#severity').onchange=renderQueue;$('#status-filter').onchange=renderQueue;$('#export-all').onclick=()=>download('risklens-september-2026-evidence.csv',csv(M.flagged),'text/csv');$('#reset').onclick=()=>{if(confirm('Clear case notes and review statuses stored in this browser?')){reviews={};save();overview();renderQueue()}};$('#chat-form').onsubmit=e=>{e.preventDefault();const q=$('#question').value.trim();if(q)ask(q)};document.querySelectorAll('.suggestions button').forEach(b=>b.onclick=()=>ask(b.textContent));$('#policy-cards').innerHTML=D.policies.map(p=>`<div class="policy-card"><div><span class="badge">${p.id} · v${p.version}</span></div><div><h3>${esc(p.name)}</h3><p><strong>${esc(p.rule)}</strong></p><p>${esc(p.description)}</p></div></div>`).join('');overview();renderQueue();
